document.addEventListener('submit',e=>{e.preventDefault();const form=e.target,data=new FormData(form),v=Object.fromEntries(data.entries()),error=msg=>{const area=$('#form-error');if(area)area.textContent=msg;else toast(msg)};
 if(form.id==='course-form'){
  if(!validDate(v.start)||!validDate(v.end)||v.start>v.end||(E.day(v.end)-E.day(v.start))/86400000>730)return error(t('Geçerli bir dönem seç (en fazla 2 yıl).','Choose a valid semester (at most 2 years).'));
  if(!v.code.trim()||!v.name.trim())return error(t('Ders kodunu ve adını gir.','Enter the course code and name.'));
  if(state.courses.some(c=>c.id!==form.dataset.id&&c.code.toLowerCase()===v.code.trim().toLowerCase()))return error(t('Bu ders kodu zaten var.','This course code already exists.'));
  const schedule=[...form.querySelectorAll('.schedule-row')].map(row=>({id:row.dataset.rule,day:Number(row.querySelector('[name=day]').value),time:row.querySelector('[name=time]').value,hours:Number(row.querySelector('[name=hours]').value),type:row.querySelector('[name=type]').value}));
  if(schedule.some(r=>minutes(r.time)+r.hours*60>1440))return error(t('Dersler gece yarısını geçemez. Oturumu ikiye böl.','Classes cannot cross midnight. Split the session in two.'));
  for(let i=0;i<schedule.length;i++)for(let j=i+1;j<schedule.length;j++){const a=schedule[i],b=schedule[j];if(a.day===b.day&&minutes(a.time)<minutes(b.time)+b.hours*60&&minutes(b.time)<minutes(a.time)+a.hours*60)return error(t('Aynı dersin haftalık oturumları çakışamaz.','Weekly sessions of the same course cannot overlap.'))}
  const old=getCourse(form.dataset.id),c={id:old?.id||uid(),code:v.code.trim(),name:v.name.trim(),start:v.start,end:v.end,required:v.required===''?null:Number(v.required),color:v.color,icon:v.icon,schedule,archived:old?.archived||false};
  const nextSessions=[...state.sessions.filter(s=>s.courseId!==c.id),...E.reconcile(c,state.sessions.filter(s=>s.courseId===c.id))];if(nextSessions.length>20000)return error(t('En fazla 20.000 oturum saklanabilir. Dönemi veya programı daralt.','Maximum 20,000 sessions. Shorten the semester or schedule.'));state.sessions=nextSessions;if(old)state.courses=state.courses.map(x=>x.id===c.id?c:x);else state.courses.push(c);closeModal();commit(t('Ders ve programı kaydedildi.','Course and timetable saved.'));
 }else if(form.id==='session-form'){
  const old=state.sessions.find(s=>s.id===form.dataset.id),s=old?.generated?{...old,status:v.status,note:v.note.trim()}:{id:old?.id||uid(),courseId:v.courseId,date:v.date,time:v.time,hours:Number(v.minutes)/60,minutes:Number(v.minutes),type:v.type,status:v.status,note:v.note.trim(),generated:false,retained:old?.retained||false};
  if(minutes(s.time)+s.hours*60>1440)return error(t('Oturum gece yarısını geçemez.','A session cannot cross midnight.'));
  if(!E.ended(s)&&['present','absent'].includes(s.status))return error(t('Katılımı ders bittikten sonra kaydet.','Record attendance after the class ends.'));
  const c=getCourse(s.courseId);if(!E.inTerm(c,s)&&!(old&&old.courseId===s.courseId&&old.date===s.date&&old.time===s.time&&old.hours===s.hours&&old.type===s.type))return error(t('Önce dersin dönem tarihlerini ayarla. Yeni kayıt bu tarihler arasında olmalı. Mevcut dönem dışı kayıtlarda yalnızca durum ve not değiştirilebilir.','Set the course semester dates first. New entries must fall within them. Existing outside-semester records allow status and note edits only.'));
  if(!old?.generated&&state.sessions.some(o=>o.id!==s.id&&o.courseId===s.courseId&&o.date===s.date&&minutes(o.time)<minutes(s.time)+s.hours*60&&minutes(s.time)<minutes(o.time)+o.hours*60&&o.status!=='cancelled'&&s.status!=='cancelled'))return error(t('Bu dersin aynı saatlerde başka bir oturumu var. Mevcut oturumu düzenle veya önce iptal et.','This course already has an overlapping session. Edit the existing session or cancel it first.'));
  if(!old&&state.sessions.length>=20000)return error(t('20.000 oturum sınırına ulaşıldı.','The 20,000 session limit has been reached.'));if(old)state.sessions=state.sessions.map(x=>x.id===s.id?s:x);else state.sessions.push(s);closeModal();commit(t('Yoklama kaydedildi.','Attendance saved.'));
 }else if(form.id==='profile-form'){state.profile={name:v.name.trim(),university:v.university.trim(),department:v.department.trim()};commit(t('Profil kaydedildi.','Profile saved.'));
 }else if(form.id==='semester-form'){
  if(!validDate(v.start)||!validDate(v.end)||v.start>v.end||(E.day(v.end)-E.day(v.start))/86400000>730)return error(t('Geçerli bir dönem seç (en fazla 2 yıl).','Choose a valid semester (at most 2 years).'));if(v.apply){const nextCourses=state.courses.map(c=>c.archived||c.official?c:{...c,start:v.start,end:v.end}),nextSessions=nextCourses.flatMap(c=>c.archived||c.official?state.sessions.filter(s=>s.courseId===c.id):E.reconcile(c,state.sessions.filter(s=>s.courseId===c.id)));if(nextSessions.length>20000)return error(t('20.000 oturum sınırı aşılır. Daha kısa bir dönem seç.','This exceeds 20,000 sessions. Choose a shorter semester.'));state.courses=nextCourses;state.sessions=nextSessions;}state.semester={start:v.start,end:v.end};commit(t('Dönem tarihleri kaydedildi.','Semester dates saved.'));
 }
});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&$('#overlay .modal')){const els=[...$('#overlay').querySelectorAll('button:not(:disabled),a,input:not(:disabled),select:not(:disabled),textarea')].filter(el=>el.offsetParent!==null),first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault()}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault()}}});
